6	/**
7	 * Enumeration per la definizione dei possibili stati assegnabili ad una Domanda Bando.
8	 *
9	 * @author costabilee
10	 *
11	 */
12	public enum StatoDomandaBandoEnum {
13	
14		BOZZA("Bozza", true), //
15		NUOVA("Nuova", false),
16		INVIATA("Inviata", false),
17		PROTOCOLLATA("Protocollata", false),
18		IN_LAVORAZIONE("In lavorazione", false), //
19		ATTESA_INTEGRAZIONI("Attesa integrazioni", false),
20		INTEGRAZIONI_INSERITE("Integrazioni inserite", false),
21		ATTESA_BROCHURE("Attesa compilazione brochure", false),
22		BROCHURE_INSERITE("Brochure inserita", false),
23		CHIUSA_POSITIVAMENTE("Chiusa con esito positivo", false),
24		CHIUSA_NEGATIVAMENTE("Chiusa con esito negativo", true),
25		ANNULLATA("Annullata", true),
26		PARTECIPAZIONE_EFFETTUATA("Partecipazione all'evento effettuata", true),
27		ASSENZA_GIUSTIFICATA("Partecipazione all'evento non effettuata (con preavviso)", true),
28		ASSENZA_NON_GIUSTIFICATA("Partecipazione all'evento non effettuata (senza preavviso)", true);
29	
30	    private String name;
31		private boolean escludereBudget;
32	
33		private StatoDomandaBandoEnum(String name, boolean escludereBudget){
34			this.name = name;
35			this.escludereBudget = escludereBudget;
36		}
37	
38		public String getName() {
39			return name;
40		}
41	
42		public void setName(String name) {
43			this.name = name;
44		}
45	
46		public boolean isEscludereBudget() {
47			return escludereBudget;
48		}
49	
50		public static StatoDomandaBandoEnum findByName(String name) {
51			StatoDomandaBandoEnum result = null;
52		    for (StatoDomandaBandoEnum statoDomandaBando : values()) {
53		        if (statoDomandaBando.name().equalsIgnoreCase(name)) {
54		            result = statoDomandaBando;
55		            break;
56		        }
57		    }
58		    return result;
59		}
60	
61		public static List<String> getNamesByEscludereBudget(boolean escludereBudget) {
62			List<String> result = new ArrayList<>();
63			for (StatoDomandaBandoEnum stato : values()) {
64				if (stato.escludereBudget == escludereBudget) {
65					result.add(stato.name());
66				}
67			}
68			return result;
69		}
70	}

